 @Override public boolean dispatchKeyEvent(KeyEvent event){if(channelOverlay!=null){if(event.getAction()==KeyEvent.ACTION_DOWN&&(event.getKeyCode()==KeyEvent.KEYCODE_BACK||event.getKeyCode()==KeyEvent.KEYCODE_MENU)){hideChannels();return true;}return super.dispatchKeyEvent(event);}if(event.getAction()==KeyEvent.ACTION_DOWN&&item!=null){int key=event.getKeyCode();if(key==KeyEvent.KEYCODE_MENU){options();return true;}if(!item.live()&&video!=null&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)&&!video.isControllerFullyVisible()){video.showController();return true;}if(!item.live()&&player!=null&&video!=null&&!video.isControllerFullyVisible()&&(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT)&&player.getDuration()>0){long seek=SeekMath.step(player.getCurrentPosition(),key==KeyEvent.KEYCODE_DPAD_RIGHT?10000:-10000,player.getDuration());player.seekTo(seek);((SeekGestureFrame)screen).show("跳转至 "+SeekMath.time(seek));return true;}if(tvMode&&(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN)){switchItem(key==KeyEvent.KEYCODE_DPAD_UP?1:-1);return true;}if(tvMode&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)&&video!=null){channels();return true;}if(key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_MEDIA_NEXT||(item.live()&&key==KeyEvent.KEYCODE_DPAD_RIGHT&&((video!=null&&video.hasFocus()&&!video.isControllerFullyVisible())||(web!=null&&web.hasFocus())))){switchItem(1);return true;}if(key==KeyEvent.KEYCODE_CHANNEL_DOWN||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS||(item.live()&&key==KeyEvent.KEYCODE_DPAD_LEFT&&((video!=null&&video.hasFocus()&&!video.isControllerFullyVisible())||(web!=null&&web.hasFocus())))){switchItem(-1);return true;}if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE&&player!=null){if(player.isPlaying())player.pause();else player.play();return true;}}return super.dispatchKeyEvent(event);}
 private void hideWebFullscreen(){if(customView!=null){android.view.ViewParent parent=customView.getParent();if(parent instanceof android.view.ViewGroup)((android.view.ViewGroup)parent).removeView(customView);customView=null;WebChromeClient.CustomViewCallback callback=customCallback;customCallback=null;if(callback!=null)callback.onCustomViewHidden();}}
